code.java:
class Solution {
    public long minimumCost(String s){
        long answer=0;
        for(int i=1;i<s.length();i++)if(s.charAt(i)!=s.charAt(i-1))answer+=Math.min(i,s.length()-i);
        return answer;
    }
}

code.kotlin:
class Solution {
    fun minimumCost(s:String):Long{
        var answer=0L;
        for(i in 1 until s.length)if(s[i]!=s[i-1])answer+=minOf(i,s.length-i);
        return answer
    }
}

